const rawJson = $input.first().json;

const body = rawJson.body ?? rawJson;



const pros_mencionados = body.pros_mencionados ?? [];

const contras_mencionados = body.contras_mencionados ?? [];

const comentarios = body.comentarios ?? [];

const total_resenas = body.total_resenas ?? 0;

const rating_promedio = body.rating_promedio ?? 0;



// Frecuencia de pros

const frecuenciaPros = {};

for (const pro of pros_mencionados) {

  const clave = pro.toLowerCase().trim();

  frecuenciaPros[clave] = (frecuenciaPros[clave] || 0) + 1;

}



// Frecuencia de contras

const frecuenciaContras = {};

for (const contra of contras_mencionados) {

  const clave = contra.toLowerCase().trim();

  frecuenciaContras[clave] = (frecuenciaContras[clave] || 0) + 1;

}



// Top 5

const topPros = Object.entries(frecuenciaPros)

  .sort((a, b) => b[1] - a[1])

  .slice(0, 5)

  .map(([texto, veces]) => `- ${texto} (mencionado ${veces} veces)`);



const topContras = Object.entries(frecuenciaContras)

  .sort((a, b) => b[1] - a[1])

  .slice(0, 5)

  .map(([texto, veces]) => `- ${texto} (mencionado ${veces} veces)`);



// Muestra de 10 comentarios aleatorios

const comentariosMuestra = [...comentarios]

  .sort(() => Math.random() - 0.5)

  .slice(0, 10);



const systemPrompt = `Eres un analizador experto de reseñas de productos en español.

Tu única función es leer datos de reseñas agregadas y devolver un análisis estructurado.

Responde SOLO con JSON válido y sin texto adicional fuera del JSON.`;



const userPrompt = `Analiza los siguientes datos agregados de reseñas de un producto y devuelve tu análisis.



DATOS DEL PRODUCTO:

- Total de reseñas analizadas: ${total_resenas}

- Rating promedio: ${rating_promedio}/5



TOP 5 ASPECTOS POSITIVOS MÁS MENCIONADOS:

${topPros.length > 0 ? topPros.join('\n') : '- Sin datos'}



TOP 5 ASPECTOS NEGATIVOS MÁS MENCIONADOS:

${topContras.length > 0 ? topContras.join('\n') : '- Sin datos'}



MUESTRA DE COMENTARIOS REALES (${comentariosMuestra.length} de ${total_resenas}):

${comentariosMuestra.map((c, i) => `[${i + 1}] "${c}"`).join('\n')}



Devuelve ÚNICAMENTE este JSON relleno:

{

  "sentimiento_general": "",

  "puntuacion_final": 0-10,

  "pros": [],

  "contras": [],

  "resumen": ""

}`;



return [{

  json: {

    groqBody: {

      model: "llama-3.3-70b-versatile",

      temperature: 0.1,

      max_tokens: 1024,

      response_format: { type: "json_object" },

      messages: [

        { role: "system", content: systemPrompt },

        { role: "user", content: userPrompt }

      ]

    },

    metadata: {

      total: total_resenas,

      rating: rating_promedio,

      top_pros: topPros,

      top_contras: topContras

    }

  }

}];

const data = $input.first().json;

// Groq devuelve la respuesta en choices[0].message.content
const content = data.choices[0].message.content;

// Como usamos response_format: json_object, ya viene como objeto
// pero por seguridad intentamos parsear si viene como string
let analisis;
try {
  analisis = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  // Si falla, intentamos limpiar posible markdown residual
  const limpio = content
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();
  const match = limpio.match(/\{[\s\S]*\}/);
  if (match) {
    analisis = JSON.parse(match[0]);
  } else {
    throw new Error('No se pudo parsear: ' + limpio);
  }
}

return [{
  json: {
    sentimiento_general: analisis.sentimiento_general ?? '',
    puntuacion_final: analisis.puntuacion_final ?? 0,
    pros: analisis.pros ?? [],
    contras: analisis.contras ?? [],
    resumen: analisis.resumen ?? '',
    metadata: {
      model: data.model ?? '',
      tokens_usados: data.usage?.total_tokens ?? 0,
      tokens_prompt: data.usage?.prompt_tokens ?? 0,
      tokens_respuesta: data.usage?.completion_tokens ?? 0
    }
  }
}];
